import sys
from functools import lru_cache


def main():
    data = sys.stdin.read().split()
    n, m = int(data[0]), int(data[1])
    grid = data[2:2 + n]
    total = n * m
    sys.setrecursionlimit(100000)

    @lru_cache(maxsize=None)
    def f(pos, mask):
        if pos == total:
            return 0
        r, c = divmod(pos, m)
        if mask & 1 or grid[r][c] == '#':
            return f(pos + 1, mask >> 1)
        best = f(pos + 1, mask >> 1)
        if c + 1 < m and not (mask & 2) and grid[r][c + 1] == '.':
            best = max(best, 1 + f(pos + 1, (mask >> 1) | 1))
        if r + 1 < n and grid[r + 1][c] == '.':
            best = max(best, 1 + f(pos + 1, (mask >> 1) | (1 << (m - 1))))
        return best

    print(f(0, 0))


main()
